package com.ddarungflow.station; import com.ddarungflow.dto.StationRhythmDtos; import com.ddarungflow.repository.StationRhythmProfileRepository; import org.springframework.stereotype.Service;
@Service public class StationRhythmService { private final StationRhythmProfileRepository repository; public StationRhythmService(StationRhythmProfileRepository repository){this.repository=repository;} public StationRhythmDtos.Response find(String id){var p=repository.findById(id).orElseThrow(NotFound::new); return new StationRhythmDtos.Response(p.getWindowStart(),p.getWindowEnd(),p.getSampleCount(),p.getPayload().path("weekdayHourly"),p.getPayload().path("stockout")); } public static class NotFound extends RuntimeException{} }
